DROP TABLE IF EXISTS `climate_data`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `climate_data` (
  `id` int NOT NULL AUTO_INCREMENT,
  `region_id` int NOT NULL,
  `date` date NOT NULL,
  `temperature` decimal(5,2) DEFAULT NULL,
  `rainfall` decimal(6,2) DEFAULT NULL,
  `humidity` decimal(5,2) DEFAULT NULL,
  `enso_index` decimal(5,2) DEFAULT NULL,
  `hot_days` decimal(6,2) DEFAULT NULL COMMENT 'days with Tmax above 35C; blank in ERA5 source is loaded as 0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_climate_region_date` (`region_id`,`date`),
  CONSTRAINT `climate_data_ibfk_1` FOREIGN KEY (`region_id`) REFERENCES `regions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=23221 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
