--
-- Table structure for table `evaluation_metrics`
--

DROP TABLE IF EXISTS `evaluation_metrics`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `evaluation_metrics` (
  `id` int NOT NULL AUTO_INCREMENT,
  `model_run_id` int NOT NULL,
  `rmse` decimal(8,3) DEFAULT NULL,
  `mae` decimal(8,3) DEFAULT NULL,
  `mape` decimal(6,3) DEFAULT NULL,
  `crps` decimal(8,3) DEFAULT NULL,
  `coverage` decimal(5,2) DEFAULT NULL,
  `scope` enum('overall','region') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'overall',
  `region_id` int DEFAULT NULL,
  `n_obs` int DEFAULT NULL,
  `mean_interval_width` decimal(10,2) DEFAULT NULL COMMENT 'sharpness',
  PRIMARY KEY (`id`),
