  `lat` decimal(9,6) DEFAULT NULL,
  `lng` decimal(9,6) DEFAULT NULL,
  `psgc_code` varchar(12) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `land_area_km2` decimal(10,2) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_region_slug` (`slug`),
  UNIQUE KEY `uniq_region_identity` (`admin_level`,`province`,`name`),
  KEY `idx_regions_level` (`admin_level`)
) ENGINE=InnoDB AUTO_INCREMENT=344 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
